INSERT INTO scheduled_tasks (id, agent_id, name, description, schedule_type, cron_expression, action, action_params, status, last_run, next_run, run_count, fail_count, created_at, enabled) VALUES
('cto-daily-health-check', 'cto-technical', 'Daily System Health Check', 'Query all system components, update health scores, flag degraded components', 'cron', '0 6 * * *', 'custom_prompt', '{"prompt":"Execute Daily System Health Check. Step 1: Query system_health DB for all components. Step 2: Identify any with health_score < 80. Step 3: Check circuit_breaker_state — any open? Step 4: Review self_heal_success_rate — below 85%? Step 5: Check tech_debt for any P1 items in ''identified'' status. Step 6: Check upgrade_log for any failed upgrades needing rollback. Produce: 1) System health summary — all components status, overall health score, 2) Degraded component alerts — any components with health_score < 80, severity and impact, 3) Self-healing effectiveness — success rate, recent healing events, trends, 4) Technical debt status — P1 items in identified status, aging of critical debt, 5) Upgrade pipeline status — any failed upgrades, rollback candidates, pending upgrades. If all components healthy (all health_scores >= 80, all circuit breakers closed, self_heal_success_rate >= 85%): reply HEARTBEAT_OK. If issues found: produce brief with prioritized actions ranked by severity. Use LifeOS-MCP tools: lifeos_query(database=''system_health''), lifeos_query(database=''tech_debt''), lifeos_query(database=''upgrade_log'').","priority":"P2"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('cto-weekly-technical-review', 'cto-technical', 'Weekly Technical Review', 'Review technical debt aging, upgrade progress, propose fixes for P1/P2 items', 'cron', '0 14 * * 0', 'custom_prompt', '{"prompt":"Execute Weekly Technical Review. Step 1: Aggregate all tech_debt items from past week. Step 2: Identify aging debt — items in ''identified'' > 7 days. Step 3: Review upgrade_log — any stuck in ''in-progress'' or ''scheduled''. Step 4: Analyze system_health trends — compare current vs last week''s health scores. Step 5: Identify recurring failures — components that degraded multiple times this week. Step 6: Propose resolution plans for P1/P2 debt items. Produce: 1) Weekly technical summary — overall system posture, key changes from last week, 2) Aging debt report — items overdue for action, days in current status, recommended next steps, 3) Upgrade pipeline status — completed, in-progress, scheduled, stuck upgrades with blockers, 4) Recurring failure analysis — components with multiple degradation events, root cause patterns, 5) Proposed fixes for P1/P2 items — specific resolution recommendations with effort estimates. Save summary to reports DB via lifeos_create_entry(database=''reports''). SYSTEMIC FLAG CHECK: If technical pattern detected affecting system reliability — recurring failures across components, cascading degradation, systemic vulnerability — send message.send to ceo-strategic with technical pattern flag and recommended strategic response. Do NOT write to systemic_journal.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('cto-monthly-system-synthesis', 'cto-technical', 'Monthly System Synthesis', 'Aggregate month technical data, identify trends, propose architectural improvements', 'cron', '0 12 1 * *', 'custom_prompt', '{"prompt":"Execute Monthly System Synthesis. Step 1: Aggregate all technical data from past month — system_health snapshots, tech_debt changes, upgrade_log entries, self-healing events. Step 2: Analyze system health trajectory — improving, stable, or declining? Compare month-start vs month-end scores. Step 3: Review tech_debt resolution rate — are we resolving faster than creating? Calculate net debt change. Step 4: Evaluate upgrade success rate — any rollbacks? Calculate upgrade success/failure ratio. Step 5: Assess self-healing effectiveness month-over-month — success rate trend, most-healed components, unhealable components. Step 6: Identify architectural patterns needing attention — repeated failure modes, scaling bottlenecks, coupling issues. Produce: 1) Monthly system health report — trajectory analysis, component-level trends, overall system posture, 2) Technical debt trend analysis — creation rate vs resolution rate, net debt change, aging distribution, priority breakdown, 3) Upgrade effectiveness review — success rate, rollback incidents, lessons learned, 4) Self-healing performance assessment — success rate trend, component effectiveness ranking, gaps in self-healing coverage, 5) Architectural recommendations — patterns needing attention, proposed improvements with priority and rationale. Save comprehensive report to reports DB via lifeos_create_entry(database=''reports''). SYSTEMIC FLAG CHECK: If systemic technical degradation detected — declining health trajectory across multiple components, accelerating tech debt accumulation, self-healing effectiveness dropping — or architecture needs fundamental change — current design cannot support projected growth, critical scalability limits approaching — send message.send to ceo-strategic with systemic technical pattern flag and architectural change proposal.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('cto-quarterly-strategy-review', 'cto-technical', 'Quarterly Technical Strategy Review', 'Architecture review, capacity planning, strategic technical decisions for next quarter', 'cron', '0 9 1 1,4,7,10 *', 'custom_prompt', '{"prompt":"Execute Quarterly Technical Strategy Review. Step 1: Review quarter''s complete technical performance — aggregate all system_health, tech_debt, upgrade_log, and self-healing data. Step 2: Architecture assessment — current systems adequate for next quarter''s goals? Identify gaps between current capabilities and projected requirements. Step 3: Capacity planning — will current infrastructure handle projected load? Analyze resource utilization trends, predict bottlenecks, recommend scaling actions. Step 4: Technology evaluation — any tools/frameworks need upgrading or replacing? Assess current tech stack against alternatives, identify end-of-life dependencies. Step 5: Technical debt portfolio analysis — total debt volume, resolution rate over quarter, acceptance rate of proposed fixes, debt-to-feature ratio. Step 6: Strategic technical proposals for next quarter — architecture changes, infrastructure investments, technology upgrades, debt reduction targets. Produce: 1) Quarterly technical report — comprehensive performance review, key metrics and trends, achievements and shortfalls, 2) Architecture readiness assessment — current architecture evaluation, gap analysis for next quarter goals, recommended changes, 3) Capacity planning projections — resource utilization trends, bottleneck predictions, scaling recommendations with cost estimates, 4) Technology recommendations — stack evaluation results, upgrade/replacement candidates, migration plans with risk assessment, 5) Strategic technical proposals for CEO approval — prioritized initiatives with business impact, resource requirements, timelines, and risk assessments. Save comprehensive report to reports DB via lifeos_create_entry(database=''reports''). SYSTEMIC FLAG CHECK: If architecture fundamentally inadequate for upcoming goals — critical capability gaps identified, current design blocks strategic objectives — or critical infrastructure investment needed — scaling limits will be hit within quarter, security vulnerability requiring immediate remediation, technology dependency at risk — send message.send to ceo-strategic with strategic technical flag, detailed gap analysis, and investment proposal with ROI justification.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1);
